package com.commercecore.payment;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.math.BigDecimal;import java.time.Instant;import java.util.*;public interface PaymentRepository extends JpaRepository<Payment,UUID>,JpaSpecificationExecutor<Payment>{Optional<Payment>findByOrderIdAndIdempotencyKey(UUID order,String key);Optional<Payment>findByIdAndCustomerId(UUID id,UUID customer);List<Payment>findAllByOrderIdOrderByCreatedAtAsc(UUID order);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select p from Payment p where p.id=:id")Optional<Payment>findLocked(@Param("id")UUID id);boolean existsByOrderIdAndStatusIn(UUID order,Collection<PaymentStatus> statuses);long countByStatus(PaymentStatus status);
 @Query("select coalesce(sum(p.amount), 0) from Payment p where (:status is null or p.status = :status) and p.createdAt >= :from and p.createdAt < :toExclusive")
 BigDecimal reportTotal(@Param("from")Instant from,@Param("toExclusive")Instant toExclusive,@Param("status")PaymentStatus status);
 @Query("select count(p) from Payment p where (:status is null or p.status = :status) and p.createdAt >= :from and p.createdAt < :toExclusive")
 long reportCount(@Param("from")Instant from,@Param("toExclusive")Instant toExclusive,@Param("status")PaymentStatus status);
 @Query("select p.status, count(p) from Payment p where p.createdAt >= :from and p.createdAt < :toExclusive group by p.status")
 List<Object[]> countByStatusBetween(@Param("from")Instant from,@Param("toExclusive")Instant toExclusive);}
